'use strict';
const fs=require('fs'),path=require('path');const{chromium}=require('playwright');
const BASE='https://plan-ex.ru/erpv2/',U=p=>new URL(p,BASE).href,OUT=path.resolve(process.env.P15_OUT||'P15_restore_route_output');fs.mkdirSync(OUT,{recursive:true});
function credential(){const e=process.env.P15_CREDENTIALS_B64||'';const a=e?JSON.parse(Buffer.from(e,'base64').toString('utf8')):[];return a.find(x=>String(x?.role||'').toUpperCase()==='SUPERADMIN')}
(async()=>{const r={status:'FAIL',records:[],selectedAction:null,restoreStatus:null,finalUrl:null,consoleErrors:[],pageErrors:[],requestFailures:[],httpFailures:[],error:null};let b,c;try{const s=credential();if(!s)throw Error('credential unavailable');b=await chromium.launch({headless:true});c=await b.newContext({viewport:{width:1920,height:1080},deviceScaleFactor:1,locale:'ru-RU',timezoneId:'Europe/Moscow'});const p=await c.newPage();p.on('console',m=>{if(m.type()==='error')r.consoleErrors.push(m.text())});p.on('pageerror',e=>r.pageErrors.push(String(e.message||e)));p.on('requestfailed',q=>r.requestFailures.push(q.url()));p.on('response',z=>{if(z.status()>=500)r.httpFailures.push({status:z.status(),url:z.url()})});await p.goto(U('login'),{waitUntil:'domcontentloaded'});await p.locator('input[name="username"],input[name="email"],input[type="text"]').first().fill(s.username);await p.locator('input[type="password"]').fill(s.password);await Promise.all([p.waitForLoadState('domcontentloaded').catch(()=>{}),p.locator('button[type="submit"],input[type="submit"]').first().click()]);await p.goto(U('superadmin/deleted-data?company_id=27&entity_type=linear_route&status=archived'),{waitUntil:'domcontentloaded'});r.records=await p.locator('form[action*="/superadmin/deleted-data/"][action$="/restore"]').evaluateAll(ns=>ns.map(n=>({action:n.getAttribute('action'),text:(n.closest('tr,.card,.panel')?.innerText||n.parentElement?.innerText||'').replace(/\s+/g,' ').slice(0,2000)})));if(r.records.length){const target=p.locator('form[action*="/superadmin/deleted-data/"][action$="/restore"]').last();r.selectedAction=await target.getAttribute('action');const nav=p.waitForNavigation({waitUntil:'domcontentloaded',timeout:30000});await target.evaluate(n=>HTMLFormElement.prototype.submit.call(n));const response=await nav;r.restoreStatus=response?.status()??null;r.finalUrl=p.url()}else{r.finalUrl=p.url()}await p.screenshot({path:path.join(OUT,'P15_015_SUPERADMIN_linear_route_restore_1920x1080.png'),fullPage:false});r.status=(r.records.length===0||r.restoreStatus===200)&&r.pageErrors.length===0&&r.requestFailures.length===0&&r.httpFailures.length===0?'PASS':'FAIL'}catch(e){r.error={name:e.name||'Error',message:String(e.message||e).slice(0,800)}}finally{if(c)await c.close().catch(()=>{});if(b)await b.close().catch(()=>{});fs.writeFileSync(path.join(OUT,'P15_RESTORE_LINEAR_ROUTE.json'),JSON.stringify(r,null,2));console.log('P15_RESTORE_LINEAR_ROUTE='+r.status);process.exitCode=r.status==='PASS'?0:1}})();
